SET client_encoding = 'UTF8';
BEGIN;
UPDATE articulos SET metadata = '{"areas": ["sociabilidad", "afectividad", "creatividad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Tarjetas de Misiones"], "objetivos": ["Fomentar la comunicación e interpretación", "Estimular la agilidad mental", "Trabajo en equipo", "Fomentar un entorno de confianza"], "justificacion_areas": "El Desafío del Silencio Comunicativo potencia la sociabilidad al enseñar a los beneficiarios de todas las unidades (desde Manada hasta Clan) a escucharse visualmente y respetar las normas del juego no verbal. Desarrolla la afectividad al cultivar la paciencia, el apoyo mutuo y la conducta asertiva ante misiones complejas. Fortalece la creatividad al estimular la innovación de señas corporales y la interpretación ágil de mensajes.", "variaciones": "<b>Silencio en la Selva (Manada):</b> Los lobatos se comunican en clave secreta no verbal para no ser descubiertos por Shere Khan.<br><b>Cadena de Nudos Silenciosa (Compañía/Tropa):</b> Transmitir las instrucciones para realizar una estructura scout utilizando únicamente mímica de manos.<br><b>Resolución de Dilemas de Pionerismo Silencioso (Avanzada/Clan):</b> La unidad mayor debe coordinar la resolución de un circuito técnico o dilema de servicio comunicándose solo con señas avanzadas.", "recomendaciones": "Generar un clima de profunda concentración y respeto por la palabra no verbal. En Avanzada y Clan, adaptar las tarjetas con desafíos de lógica y liderazgo de equipo.", "objetivos_educativos": [{"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Acatando con lealtad la regla de no hablar durante el desarrollo de la prueba."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Respetando los turnos de expresión no verbal de mis compañeros de seisena."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando el respeto y la atención dedicada hacia las señas de las demás personas."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo un ambiente de integración, escucha atenta y lealtad de patrulla."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Cumpliendo las consignas del silencio scout con responsabilidad compartida."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y hermandad comunitaria en toda la Tropa."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Asumiendo el silencio reflexivo como una herramienta de autorregulación y madurez grupal."}, {"id": "b5a81328-5c07-41bd-a1ea-1ed401762841", "area": "Sociabilidad", "unidad": "Clan", "texto": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "como_se_cumple": "Ejerciendo la libertad de expresión gestual de forma solidaria y respetuosa en el Clan."}, {"id": "ab6e594f-b0a0-4e6d-96aa-7779299b02ef", "area": "Afectividad", "unidad": "Manada", "texto": "Trato con cariño a los demás en la Manada y me gusta que me traten igual.", "como_se_cumple": "Demostrando atención y afecto sincero hacia los compañeros al interpretar sus gestos."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "unidad": "Manada", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "como_se_cumple": "Comunicando intenciones con respeto sin burlas ante las dificultades del silencio."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "unidad": "Compañía", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Escuchando con atención visual al compañero para sintonizar con su estado de ánimo."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "unidad": "Compañía", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "como_se_cumple": "Expresando impresiones con asertividad no verbal y empatía de equipo."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "unidad": "Tropa", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Desarrollando empatía no verbal para comprender las intenciones de la patrulla."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "unidad": "Tropa", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "como_se_cumple": "Demostrando lealtad y apoyo afectivo sincero hacia cada integrante del grupo."}, {"id": "d24ef58c-8306-4065-9625-8f5e663febcb", "area": "Afectividad", "unidad": "Avanzada", "texto": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "como_se_cumple": "Expresando empatía no verbal y apoyo asertivo a los compañeros durante retos complejos."}, {"id": "d0ba748f-313b-4ffe-b2a3-fb21c1f8943f", "area": "Afectividad", "unidad": "Clan", "texto": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "como_se_cumple": "Fomentando el clima de confianza y la contención afectiva madura en el Clan."}]}'::jsonb WHERE slug = 'el-desafio-del-silencio-comunicativo';
DELETE FROM articulo_objetivos_educativos WHERE articulo_id = (SELECT id FROM articulos WHERE slug = 'el-desafio-del-silencio-comunicativo');
COMMIT;